}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}

.site-header {
  padding: 28px 20px 10px;
  max-width: 960px;
  margin: 0 auto;
}

.site-header h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  color: var(--accent);
}

.subtitle {
  margin: 0;
  color: var(--muted);
}

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 12px 20px 24px;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 18px 20px;
  margin-bottom: 18px;
  box-shadow: 0 1px 3px rgba(20, 40, 35, 0.06);
}

.card h2 {
  margin: 0 0 12px;
  font-size: 1.1rem;
}

code {
  background: var(--accent-soft);
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 0.9em;
}

.muted { color: var(--muted); }
.strong { font-weight: 600; }

/* ------------------------- Controls ------------------------ */
.controls-card {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.controls-card .label {
  font-weight: 600;
  margin-right: 4px;
}

select {
  font-size: 1rem;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
}

.controls-hint {
  color: var(--muted);
  font-size: 0.95rem;
}

/* ------------------------- Chart --------------------------- */
.chart { display: grid; gap: 10px; }

.chart-row {
  display: grid;
  grid-template-columns: 170px 1fr 92px;
  align-items: center;
  gap: 10px;
}

.chart-label {
  display: flex;
  align-items: center;
  gap: 8px;
}

.chart-rank {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 0.8rem;
  font-weight: 700;
  flex: 0 0 auto;
}

.chart-district { font-weight: 600; }

.chart-track {
  position: relative;
  background: #eef2f1;
  border-radius: 6px;
  height: 26px;
  overflow: hidden;
}

.chart-bar {
  height: 100%;
  background: #4fa893;
  border-radius: 6px 0 0 6px;
  transition: width 0.3s ease;
}

.chart-bar-top { background: var(--accent); }

.chart-value {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--ink);
}

.chart-delta {
  font-size: 0.85rem;
  text-align: right;
  white-space: nowrap;
}

/* ------------------------- Table --------------------------- */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.data-table th,
.data-table td {
  padding: 9px 10px;
  border-bottom: 1px solid var(--line);
  text-align: left;
}

.data-table th {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--muted);
}

.data-table tbody tr:hover { background: #f6faf9; }

/* ------------------------- Deltas -------------------------- */
.delta-up { color: var(--up); font-weight: 600; }
.delta-down { color: var(--down); font-weight: 600; }
.delta-na { color: var(--na); }

/* ------------------------- Info panels --------------------- */
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.formula {
  font-size: 0.95rem;
  background: var(--accent-soft);
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 10px;
}

.frac {
  display: inline-block;
  vertical-align: middle;
  text-align: center;
  margin: 0 6px;
  font-size: 0.85em;
}

.frac .num {
  display: block;
  border-bottom: 1.5px solid var(--ink);
  padding: 0 6px 2px;
}

.frac .den {
  display: block;
  padding: 2px 6px 0;
}

.formula-notes {
  margin: 0;
  padding-left: 20px;
  color: var(--muted);
  font-size: 0.92rem;
}

.formula-notes li { margin-bottom: 6px; }

/* ------------------------- Footer -------------------------- */
.site-footer {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 20px 30px;
  color: var(--muted);
  font-size: 0.85rem;
}

/* ------------------------- Small screens ------------------- */
@media (max-width: 720px) {
  .two-col { grid-template-columns: 1fr; }
  .chart-row {
    grid-template-columns: 110px 1fr 84px;
  }
  .chart-district { font-size: 0.9rem; }
}

